RandomManager::RandomManager(void)
{
    uint32_t seed;
    otError  error;

    Entropy::Init();

    error = Entropy::GetUint32(seed);
    assert(error == OT_ERROR_NONE);

    Random::NonCrypto::Seed(seed);

#ifndef OPENTHREAD_RADIO
    Random::Crypto::Init();
#endif
}

RandomManager::~RandomManager(void)
{
#ifndef OPENTHREAD_RADIO
    Random::Crypto::Deinit();
#endif
    Entropy::Deinit();
}

